impl HostDispatcher for RejectHostDispatcher {
    fn invoke(&mut self, _vm: &mut Vm, key: u32, _args: &[Value]) -> Result<Vec<Value>> {
        Err(Error::new(ErrorKind::HostDispatcherUnavailable { key }).without_source_location())
    }
}

