    #[test]
    fn explicit_collection_prunes_only_unreachable_coroutine_state() {
        let mut vm = Vm::new(Profile::ReproducibleStandard);
        let live_handle = vm
            .heap
            .alloc_userdata(None)
            .expect("live coroutine userdata");
        let dead_handle = vm
            .heap
            .alloc_userdata(None)
            .expect("dead coroutine userdata");
        let live_root = vm.retain_value(Value::userdata(live_handle)).unwrap();
        for handle in [live_handle, dead_handle] {
            vm.coroutines.push(CoroutineState {
                handle,
                callee: Value::nil(),
                frames: Vec::new(),
                initialized: false,
                dead: false,
                error: None,
                debug_snapshot: None,
            });
        }

        vm.collect_garbage();

        assert_eq!(vm.coroutines.len(), 1);
        assert_eq!(vm.coroutines[0].handle, live_handle);
        assert!(vm.heap.has_userdata(live_handle));
        assert!(!vm.heap.has_userdata(dead_handle));
        drop(live_root);
        vm.collect_garbage();
        assert!(vm.coroutines.is_empty());
        assert!(!vm.heap.has_userdata(live_handle));
    }

    #[test]
    fn suspended_coroutine_frames_follow_handle_reachability_to_a_fixed_point() {
        let mut vm = Vm::new(Profile::ReproducibleStandard);
        let first_handle = vm
            .heap
            .alloc_userdata(None)
            .expect("first coroutine userdata");
        let second_handle = vm
            .heap
            .alloc_userdata(None)
            .expect("second coroutine userdata");
        let payload = vm.heap.alloc_array_table(&[Value::number(42.0)]);
        let environment = vm.globals;
        let snapshot = |root| CoroutineDebugSnapshot {
            frames: vec![CallStackFrame {
                program: None,
                function: None,
                debug_name: None,
                environment,
                call_site: None,
                roots: vec![root],
                stackless_roots: Vec::new(),
                stackless_debug_frames: Vec::new(),
            }],
            top_location: None,
            first_debug_info_level: 0,
        };
        vm.coroutines.push(CoroutineState {
            handle: first_handle,
            callee: Value::nil(),
            frames: Vec::new(),
            initialized: true,
            dead: false,
            error: None,
            debug_snapshot: Some(snapshot(Value::userdata(second_handle))),
        });
        vm.coroutines.push(CoroutineState {
            handle: second_handle,
            callee: Value::nil(),
            frames: Vec::new(),
            initialized: true,
            dead: false,
            error: None,
            debug_snapshot: Some(snapshot(Value::table(payload))),
        });
        let first_root = vm
            .retain_value(Value::userdata(first_handle))
            .expect("first coroutine root");

        vm.collect_garbage();

        assert_eq!(vm.coroutines.len(), 2);
        assert!(vm.heap.has_userdata(first_handle));
        assert!(vm.heap.has_userdata(second_handle));
        assert!(vm.heap.has_table(payload));

        drop(first_root);
        vm.collect_garbage();

        assert!(vm.coroutines.is_empty());
        assert!(!vm.heap.has_userdata(first_handle));
        assert!(!vm.heap.has_userdata(second_handle));
        assert!(!vm.heap.has_table(payload));
    }

    #[test]
    fn compiled_short_literals_stay_inline_until_atom_identity_is_required() {
        for (bytes, should_inline) in [
            (b"1234567890123".as_slice(), true),
            (b"12345678901234".as_slice(), false),
        ] {
            let program = Program::new(
                Function::new(
                    vec![
                        Instruction::new(Opcode::LoadConst, 0, 0, 0),
                        Instruction::new(Opcode::Return, 0, 1, 0),
                    ],
                    1,
                ),
                vec![Constant::String(bytes.to_vec())],
            );
            let mut vm = Vm::new(Profile::ReproducibleStandard);
            let value = vm.run(&program).expect("compiled string literal");
            let cached_atom = vm
                .dynamic_programs
                .last()
                .expect("run should retain the program")
                .constant_atom(0);

            assert_eq!(value.as_short_string().is_some(), should_inline);
            assert_eq!(cached_atom.is_none(), should_inline);
            assert_eq!(
                vm.string_value_bytes(value)
                    .expect("valid string representation")
                    .as_deref(),
                Some(bytes)
            );
        }
    }

    #[test]
    fn loaded_program_metadata_is_compact_and_cache_site_scoped() {
        let mut code = vec![Instruction::new(Opcode::Halt, 0, 0, 0); 256];
        code[17] = Instruction::new(Opcode::GetGlobal, 0, 0, 0);
        code[213] = Instruction::new(Opcode::SetIndex, 0, 1, 2);
        let program = Program::new(
            Function::new(code, 3),
            vec![Constant::String(b"field".to_vec()); 32],
        );
        let loaded = LoadedProgram::new(program);

        assert_eq!(std::mem::size_of::<u32>(), 4);
        assert_eq!(std::mem::size_of::<TableStringInlineCache>(), 16);
        assert_eq!(std::mem::size_of::<FunctionCapture>(), 16);
        assert_eq!(
            std::mem::size_of_val(loaded.constant_atoms.as_slice()),
            32 * std::mem::size_of::<u32>()
        );
        assert_eq!(loaded.main_inline_caches.entry_by_pc.len(), 256);
        assert_eq!(
            loaded
                .main_inline_caches
                .entry_by_pc
                .iter()
                .filter(|&&entry| entry == SITE_CACHE_TABLE_EMPTY)
                .count(),
            2
        );
        assert!(loaded.main_inline_caches.table_entries.is_empty());
        assert!(loaded.main_inline_caches.closure_call_entries.is_none());
        assert!(
            std::mem::size_of_val(loaded.main_inline_caches.entry_by_pc.as_slice())
                < 256 * std::mem::size_of::<Option<TableStringInlineCache>>()
        );
    }

